ap=argparse.ArgumentParser(); ap.add_argument("--dev-text",required=True); ap.add_argument("--dev-probs",required=True); ap.add_argument("--a-predict-dir",required=True); ap.add_argument("--output",required=True); a=ap.parse_args()
dev_path=Path(a.dev_text).expanduser().resolve(); probs_path=Path(a.dev_probs).expanduser().resolve(); api_dir=Path(a.a_predict_dir).expanduser().resolve(); api=api_dir/"A_predict.py"; out=Path(a.output).expanduser().resolve(); paths=[dev_path,probs_path,api_dir,api,out,Path(__file__).resolve()]
