assert api_dir.name.lower()=="reports_v2" and api.is_file() and hashlib.sha256(api.read_bytes()).hexdigest()=="ca7c2752a4863f2a24b20ec7cd9000b651d83a0cfc39709f0080ebcbdad0a053", "Missing or unexpected A_predict.py SHA-256"
sys.dont_write_bytecode=True; os.environ.update(PROJECT_S_ROOT=str(api_dir.parent),HF_HUB_OFFLINE="1",TRANSFORMERS_OFFLINE="1"); sys.path.insert(0,str(api_dir)); import A_predict; assert Path(A_predict.__file__).resolve()==api and hashlib.sha256(Path(A_predict.__file__).read_bytes()).hexdigest()=="ca7c2752a4863f2a24b20ec7cd9000b651d83a0cfc39709f0080ebcbdad0a053", "Imported A_predict path/hash mismatch"
dev=pd.read_parquet(dev_path); probs=pd.read_parquet(probs_path); rc=[f"d_p{k}" for k in range(5)]; need=["uid","dataset","split","question_id","label5","question","reference_answer","student_answer"]
assert set(need)<=set(dev.columns) and {"uid","split","label5",*rc}<=set(probs.columns), "Missing required dev-text/dev-probs columns"
assert len(dev)==len(probs)==2049 and dev.uid.is_unique and probs.uid.is_unique and set(dev.uid)==set(probs.uid), "Expected equal UID sets with 2,049 unique rows"
m=dev.merge(probs[["uid","split","label5",*rc]],on="uid",suffixes=("","_prob"),validate="one_to_one")
assert not m.split.astype(str).str.contains("test",case=False,regex=False).any() and m.split.astype(str).equals(m.split_prob.astype(str)) and m.label5.astype(str).equals(m.label5_prob.astype(str)), "Split or label5 mismatch, or test split found"
order=A_predict.LABEL5_ORDER; assert len(order)==5, "Expected five LABEL5_ORDER labels"; fn=["nli_f_ent_mean","nli_f_ent_min","nli_f_con_max","nli_f_neu_mean","nli_r_ent","nli_r_con","nli_r_neu"]; T=float(A_predict._load_policy().get("temperature",1.0)); parts=[]; start=time.perf_counter()
with torch.inference_mode():
 for s in range(0,len(m),8):
  b=m.iloc[s:s+8]; items=b[["question","reference_answer","student_answer"]].to_dict("records"); c=A_predict.component_probs(items,dataset="pooled"); p5=(c["ft"]+c["sb"]+c["nl"])/3; p3=A_predict._to3(p5); q=np.clip(p3,1e-9,1.0)**(1.0/T); p3=np.where(T!=1.0,q/q.sum(1,keepdims=True),p3)
  parts.append(pd.DataFrame({"uid":b.uid.to_numpy(),**{f"{part}_p{k}":c[part][:,k] for part in ("ft","sb","nl") for k,_ in enumerate(order)},**{name:c["feats"][:,k] for k,name in enumerate(fn)},**{f"p_{name}":p3[:,k] for k,name in enumerate(("incorrect","partial","correct"))}}))
out=pd.concat(parts,ignore_index=True); assert len(out)==2049 and out.uid.is_unique and set(out.uid)==set(probs.uid), "Component output UID/count mismatch"; prob_cols=[f"{part}_p{k}" for part in ("ft","sb","nl") for k,_ in enumerate(order)]; pooled5=np.column_stack([(out[f"ft_p{k}"]+out[f"sb_p{k}"]+out[f"nl_p{k}"])/3 for k in range(5)]); chk=pd.DataFrame({"uid":out.uid,**{f"pool_p{k}":pooled5[:,k] for k in range(5)}}).merge(probs[["uid",*rc]],on="uid",validate="one_to_one"); diffs=np.abs(chk[[f"pool_p{k}" for k in range(5)]].to_numpy()-chk[rc].to_numpy()); assert np.isfinite(diffs).all(), "Non-finite parity values; no output written"; rowmax=diffs.max(1); maxdiff=float(rowmax.max()); worst=chk.assign(max_abs_diff=rowmax).nlargest(5,"max_abs_diff").uid.tolist()
