out.to_parquet(out_path,index=False); stats=out[prob_cols].agg(["mean","std","min","max"]).T; print("parity_max_abs_diff",maxdiff,"rows",len(out)); print(stats.to_string()); print("nl_std_below_1e-4",bool((stats.loc[[c for c in prob_cols if c.startswith("nl_")],"std"]<1e-4).any())); print("LABEL5_ORDER",order,"runtime_seconds",time.perf_counter()-start,"GPU",torch.cuda.get_device_name(0) if torch.cuda.is_available() else "CPU")

